DO $variant_part1_runtime$
DECLARE spec jsonb; required jsonb; before_function pg_catalog.pg_proc%rowtype;
 after_function pg_catalog.pg_proc%rowtype; actual jsonb; definition text;
 config constant jsonb := '[{"signature":"public.canonical_onboard_customer_graph(jsonb)","before":"863d75ad1ffd558b2810a31184f20712","after":"c2edda31f52065fe15c750b297091cdd","canonical_complete":"c2edda31f52065fe15c750b297091cdd","original":"\ndeclare\n  v_command jsonb := coalesce(p_command, ''{}''::jsonb);\n  v_status text;\n  v_has_signed_document boolean;\n  v_has_catalog_offer boolean;\nbegin\n  if v_command->>''channel'' = ''admin'' and jsonb_typeof(v_command->''contract'') = ''object'' then\n    v_status := nullif(v_command#>>''{contract,status}'', '''');\n    v_has_signed_document := coalesce((v_command#>>''{legal,acceptance_snapshot,signedAgreementUploaded}'')::boolean, false);\n    v_has_catalog_offer := nullif(v_command#>>''{contract,contract_offer_id}'', '''') is not null;\n\n    -- A real signed document must be imported as evidence after the base graph\n    -- exists. Direct signed/active INSERT is deliberately forbidden by the\n    -- customer_contract state machine.\n    if v_has_signed_document and v_status in (''signed'', ''active'') then\n      v_command := jsonb_set(\n        v_command,\n        ''{contract,status}'',\n        to_jsonb(case when v_has_catalog_offer then ''pending_signature'' else ''draft'' end),\n        true\n      );\n      v_command := jsonb_set(v_command, ''{contract,signed_at}'', ''null''::jsonb, true);\n    elsif not v_has_catalog_offer and v_status = ''pending_signature'' then\n      -- One-off/manual contracts need their exact canonical publication chain\n      -- materialized before they can enter pending_signature.\n      v_command := jsonb_set(v_command, ''{contract,status}'', ''\"draft\"''::jsonb, true);\n      v_command := jsonb_set(v_command, ''{contract,signed_at}'', ''null''::jsonb, true);\n    end if;\n  end if;\n\n  return public.gridex_onboard_customer_graph(v_command);\nend\n","patched":"\ndeclare\n  v_command jsonb := coalesce(p_command, ''{}''::jsonb);\n  v_status text;\n  v_has_signed_document boolean;\n  v_has_catalog_offer boolean;\nbegin\n  if v_command->>''channel'' = ''admin'' and jsonb_typeof(v_command->''contract'') = ''object'' then\n    v_status := nullif(v_command#>>''{contract,status}'', '''');\n    v_has_signed_document := coalesce((v_command#>>''{legal,acceptance_snapshot,signedAgreementUploaded}'')::boolean, false);\n    v_has_catalog_offer := nullif(v_command#>>''{contract,contract_offer_id}'', '''') is not null;\n\n    -- A real signed document must be imported as evidence after the base graph\n    -- exists. Direct signed/active INSERT is deliberately forbidden by the\n    -- customer_contract state machine.\n    if v_has_signed_document and v_status in (''signed'', ''active'') then\n      v_command := jsonb_set(\n        v_command,\n        ''{contract,status}'',\n        to_jsonb(case when v_has_catalog_offer then ''pending_signature'' else ''draft'' end),\n        true\n      );\n      v_command := jsonb_set(v_command, ''{contract,signed_at}'', ''null''::jsonb, true);\n    elsif not v_has_catalog_offer and v_status = ''pending_signature'' then\n      -- One-off/manual contracts need their exact canonical publication chain\n      -- materialized before they can enter pending_signature.\n      v_command := jsonb_set(v_command, ''{contract,status}'', ''\"draft\"''::jsonb, true);\n      v_command := jsonb_set(v_command, ''{contract,signed_at}'', ''null''::jsonb, true);\n    end if;\n  end if;\n\n  if v_command->>''channel''=''ediel_inbound'' and v_command#>>''{application,source_record_type}''=''ediel_inbound_case'' and strpos(coalesce(v_command#>>''{application,source_record_id}'',''''),'':object:'')>0 then\n    return gridex_prodat_object_batch.onboard_v1(v_command);\n  end if;\n  return public.gridex_onboard_customer_graph(v_command);\nend\n","source_line":39035,"source_statement_sha256":"164877930dbc2d7748ab81e0c57a2bc57332e83fa52e3199c58521e0e2b4d338","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_command"],"proargmodes":null,"return_type":"jsonb","proretset":false,"identity_arguments":"p_command jsonb","arguments":"p_command jsonb","language":"plpgsql"}},{"signature":"public.gridex_create_billing_export_run(jsonb,jsonb)","before":"f54cbf6ddcb6b4c28c1ff818aa62ebbd","after":"d95a237ce43c9822679b6b36c64aa1c3","canonical_complete":"d95a237ce43c9822679b6b36c64aa1c3","original":"\ndeclare\n  v_company_id uuid:=nullif(p_run->>''company_id'','''')::uuid;\n  v_run_id uuid:=coalesce(nullif(p_run->>''id'','''')::uuid,gen_random_uuid());\n  v_existing public.billing_export_runs%rowtype;\n  v_run public.billing_export_runs%rowtype;\n  v_item jsonb;\n  v_underlay public.billing_underlays%rowtype;\n  v_item_contract_id uuid;\n  v_pricing_run_id uuid;\n  v_rows integer:=0;\nbegin\n  if v_company_id is null or nullif(p_run->>''period_month'','''') is null then\n    raise exception using errcode=''22023'',message=''export_company_and_period_required'';\n  end if;\n  if jsonb_typeof(coalesce(p_items,''[]''::jsonb))<>''array'' then\n    raise exception using errcode=''22023'',message=''export_items_must_be_array'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text||'':''||coalesce(p_run->>''idempotency_key'',v_run_id::text),0));\n\n  if nullif(p_run->>''idempotency_key'','''') is not null then\n    select * into v_existing from public.billing_export_runs\n    where company_id=v_company_id and idempotency_key=p_run->>''idempotency_key''\n    order by created_at limit 1;\n    if found then return to_jsonb(v_existing); end if;\n  end if;\n\n  insert into public.billing_export_runs(\n    id,company_id,period_month,target_system,export_format,status,rows_total,rows_ready,\n    rows_blocked,rows_exported,blocker_summary,metadata,created_by,created_at,updated_at,\n    adapter_key,payload_version,retry_policy,idempotency_key\n  ) values (\n    v_run_id,v_company_id,p_run->>''period_month'',coalesce(nullif(p_run->>''target_system'',''''),''billing_partner''),\n    coalesce(nullif(p_run->>''export_format'',''''),''json''),coalesce(nullif(p_run->>''status'',''''),''blocked''),\n    coalesce((p_run->>''rows_total'')::integer,0),coalesce((p_run->>''rows_ready'')::integer,0),\n    coalesce((p_run->>''rows_blocked'')::integer,0),coalesce((p_run->>''rows_exported'')::integer,0),\n    coalesce(p_run->''blocker_summary'',''[]''::jsonb),coalesce(p_run->''metadata'',''{}''::jsonb),\n    nullif(p_run->>''created_by'','''')::uuid,coalesce(nullif(p_run->>''created_at'','''')::timestamptz,now()),\n    coalesce(nullif(p_run->>''updated_at'','''')::timestamptz,now()),\n    coalesce(nullif(p_run->>''adapter_key'',''''),''gridex_billing_partner_v1''),\n    coalesce(nullif(p_run->>''payload_version'',''''),''billing_export_v4c''),\n    coalesce(p_run->''retry_policy'',''{\"maxAttempts\":3,\"strategy\":\"manual_retry\"}''::jsonb),\n    nullif(p_run->>''idempotency_key'','''')\n  ) returning * into v_run;\n\n  for v_item in select value from jsonb_array_elements(coalesce(p_items,''[]''::jsonb)) loop\n    if nullif(v_item->>''billing_underlay_id'','''') is null then\n      raise exception using errcode=''23514'',message=''export_item_underlay_required'';\n    end if;\n    select * into v_underlay from public.billing_underlays\n    where id=(v_item->>''billing_underlay_id'')::uuid and company_id=v_company_id for share;\n    if not found then raise exception using errcode=''23503'',message=''export_item_underlay_not_found_for_tenant''; end if;\n\n    v_item_contract_id:=nullif(v_item->>''contract_id'','''')::uuid;\n    if coalesce(v_item->>''status'',''blocked'')=''ready'' then\n      if v_item_contract_id is null or v_underlay.contract_id is distinct from v_item_contract_id then\n        raise exception using errcode=''23514'',message=''export_item_contract_must_match_underlay_exactly'';\n      end if;\n      if coalesce(v_underlay.contract_price_snapshot_id,v_underlay.pricing_snapshot_id) is null then\n        raise exception using errcode=''23514'',message=''export_item_exact_price_snapshot_required'';\n      end if;\n      v_pricing_run_id:=nullif(v_item#>>''{payload_snapshot,pricing,pricingRunId}'','''')::uuid;\n      if v_pricing_run_id is null or not exists(\n        select 1 from public.pricing_runs pr\n        where pr.id=v_pricing_run_id and pr.company_id=v_company_id\n          and pr.billing_underlay_id=v_underlay.id and pr.status=''locked''\n      ) then\n        raise exception using errcode=''23514'',message=''export_item_locked_pricing_run_required'';\n      end if;\n    end if;\n\n    insert into public.billing_export_run_items(\n      id,company_id,billing_export_run_id,billing_underlay_id,contract_id,customer_id,site_id,metering_point_id,\n      status,readiness_status,blocker_reasons,pricing_line_items,invoice_recipient,invoice_email,invoice_reference,\n      billing_level,consolidated_invoice,invoice_address_snapshot,site_address_snapshot,consolidated_invoice_group_key,\n      adapter_key,payload_version,adapter_payload_snapshot,external_reference,payload_snapshot,export_status,\n      idempotency_key,created_at,updated_at\n    ) values (\n      coalesce(nullif(v_item->>''id'','''')::uuid,gen_random_uuid()),v_company_id,v_run.id,v_underlay.id,v_item_contract_id,\n      nullif(v_item->>''customer_id'','''')::uuid,nullif(v_item->>''site_id'','''')::uuid,nullif(v_item->>''metering_point_id'','''')::uuid,\n      coalesce(nullif(v_item->>''status'',''''),''blocked''),coalesce(nullif(v_item->>''readiness_status'',''''),''blocked''),\n      coalesce(v_item->''blocker_reasons'',''[]''::jsonb),coalesce(v_item->''pricing_line_items'',''[]''::jsonb),\n      nullif(v_item->>''invoice_recipient'',''''),nullif(v_item->>''invoice_email'',''''),nullif(v_item->>''invoice_reference'',''''),\n      coalesce(nullif(v_item->>''billing_level'',''''),''customer''),coalesce((v_item->>''consolidated_invoice'')::boolean,false),\n      coalesce(v_item->''invoice_address_snapshot'',''{}''::jsonb),coalesce(v_item->''site_address_snapshot'',''{}''::jsonb),\n      nullif(v_item->>''consolidated_invoice_group_key'',''''),coalesce(nullif(v_item->>''adapter_key'',''''),''gridex_billing_partner_v1''),\n      coalesce(nullif(v_item->>''payload_version'',''''),''billing_export_item_v4c''),coalesce(v_item->''adapter_payload_snapshot'',''{}''::jsonb),\n      nullif(v_item->>''external_reference'',''''),coalesce(v_item->''payload_snapshot'',''{}''::jsonb),\n      coalesce(nullif(v_item->>''export_status'',''''),''not_queued''),nullif(v_item->>''idempotency_key'',''''),\n      coalesce(nullif(v_item->>''created_at'','''')::timestamptz,now()),coalesce(nullif(v_item->>''updated_at'','''')::timestamptz,now())\n    );\n    v_rows:=v_rows+1;\n  end loop;\n\n  if v_rows<>coalesce((p_run->>''rows_total'')::integer,0) then\n    raise exception using errcode=''23514'',message=''export_run_item_count_mismatch'';\n  end if;\n  return to_jsonb(v_run);\nend\n","patched":"\nDECLARE item jsonb;company uuid;\nBEGIN\n IF coalesce(current_setting(''role'',true),'''')<>''service_role'' AND current_user<>''service_role'' AND session_user<>''service_role'' THEN RAISE EXCEPTION ''service_role_required'' USING ERRCODE=''42501''; END IF;\n company:=(p_run->>''company_id'')::uuid;\n IF company IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''billing_export_source_scope_required''; END IF;\n FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP\n  IF item->>''status''=''ready'' THEN PERFORM gridex_billing_source.require_underlay_v1(company,(item->>''billing_underlay_id'')::uuid); END IF;\n END LOOP;\n RETURN gridex_billing_source.gridex_create_billing_export_run_before_source_v2(p_run,p_items);\nEND ","source_line":61034,"source_statement_sha256":"843557062516447a41c46fe81bc800cec66ad8e98dc960a269f67e04b58c77e2","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public, extensions, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_run","p_items"],"proargmodes":null,"return_type":"jsonb","proretset":false,"identity_arguments":"p_run jsonb, p_items jsonb","arguments":"p_run jsonb, p_items jsonb DEFAULT ''[]''::jsonb","language":"plpgsql"}},{"signature":"public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(uuid,uuid,text)","before":"fa3c52d78347d7dfc7823886453a837d","after":"5fc99b3c1d7a45019ec048a1f8c209bb","canonical_complete":"5fc99b3c1d7a45019ec048a1f8c209bb","original":"\ndeclare\n  v_company public.companies%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\nbegin\n  if p_company_id is null then raise exception ''company_id_required''; end if;\n  select * into v_company from public.companies where id = p_company_id for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  v_payload := jsonb_build_object(\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n      ''test_ediel_id'', v_company.test_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', v_company.brp_ediel_id,\n      ''test_application_reference'', v_company.test_application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''test_sender_sub_address'', v_company.test_sender_sub_address,\n      ''production_sender_sub_address'', v_company.production_sender_sub_address,\n      ''test_mailbox'', v_company.test_mailbox,\n      ''production_mailbox'', v_company.production_mailbox,\n      ''primary_test_route_id'', v_company.ediel_primary_test_route_profile_id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', a.id,\n        ''environment'', a.environment,\n        ''actor_role'', coalesce(a.actor_role, a.role),\n        ''ediel_id'', coalesce(a.actor_ediel_id, a.ediel_id),\n        ''sender_subaddress'', coalesce(a.sender_sub_address, a.sender_subaddress),\n        ''receiver_subaddress'', coalesce(a.receiver_sub_address, a.receiver_subaddress),\n        ''application_reference'', coalesce(a.application_reference, a.default_application_reference),\n        ''mailbox'', a.mailbox,\n        ''brp_ediel_id'', a.brp_ediel_id,\n        ''is_active'', a.is_active\n      ) order by a.environment, a.id)\n      from public.ediel_actor_settings a\n      where a.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', r.id,\n        ''environment'', r.environment,\n        ''route_type'', r.route_type,\n        ''sender_ediel_id'', r.sender_ediel_id,\n        ''sender_subaddress'', coalesce(r.sender_sub_address, r.sender_subaddress),\n        ''receiver_ediel_id'', r.receiver_ediel_id,\n        ''receiver_subaddress'', coalesce(r.receiver_sub_address, r.receiver_subaddress),\n        ''mailbox_id'', r.mailbox_id,\n        ''transport_profile_id'', r.transport_profile_id,\n        ''certificate_id'', r.certificate_id,\n        ''receiver_certificate_id'', r.receiver_certificate_id,\n        ''is_active'', r.is_active,\n        ''is_enabled'', r.is_enabled\n      ) order by r.environment, r.id)\n      from public.ediel_route_profiles r\n      where r.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', m.id,\n        ''environment'', m.environment,\n        ''mailbox_name'', m.mailbox_name,\n        ''email_address'', m.email_address,\n        ''imap_host'', m.imap_host,\n        ''imap_port'', m.imap_port,\n        ''provider'', m.provider,\n        ''mailbox_type'', m.mailbox_type,\n        ''is_active'', m.is_active,\n        ''is_shared_platform_mailbox'', m.is_shared_platform_mailbox,\n        ''secret_reference_present'', m.secret_reference is not null\n      ) order by m.environment, m.id)\n      from public.ediel_mailboxes m\n      where m.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', c.id,\n        ''fingerprint'', c.certificate_fingerprint,\n        ''valid_from'', c.certificate_valid_from,\n        ''valid_to'', c.certificate_valid_to,\n        ''encryption_status'', c.encryption_status,\n        ''status'', c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''active_test_configurations'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''environment'', tc.environment,\n        ''test_suite'', tc.test_suite,\n        ''actor_role'', tc.actor_role,\n        ''message_family'', tc.message_family,\n        ''setup_package'', tc.setup_package,\n        ''status'', tc.status\n      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)\n      from public.ediel_active_test_configurations tc\n      where tc.company_id = p_company_id and tc.status = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rv.id,\n        ''rule_key'', rv.rule_key,\n        ''version_code'', rv.version_code,\n        ''schema_version'', rv.schema_version,\n        ''environment'', rv.environment,\n        ''message_family'', rv.message_family,\n        ''message_code'', rv.message_code,\n        ''business_process'', rv.business_process,\n        ''source_version'', rv.source_version,\n        ''status'', rv.status,\n        ''is_active'', rv.is_active\n      ) order by rv.rule_key, rv.version_code, rv.id)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active, false) = true\n        and coalesce(rv.status, ''active'') = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_packs'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rp.id,\n        ''market'', rp.market,\n        ''family'', rp.family,\n        ''guide_version'', rp.guide_version,\n        ''guide_revision'', rp.guide_revision,\n        ''unh_association_code'', rp.unh_association_code,\n        ''valid_from'', rp.valid_from,\n        ''valid_to'', rp.valid_to,\n        ''status'', rp.status,\n        ''source_hash'', rp.source_hash,\n        ''field_matrix_version'', rp.field_matrix_version,\n        ''code_list_versions'', rp.code_list_versions\n      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)\n      from public.ediel_rule_packs rp\n      where rp.status = ''active''\n    ), ''[]''::jsonb),\n    ''enabled_message_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', mp.id,\n        ''rule_pack_id'', mp.rule_pack_id,\n        ''message_code'', mp.message_code,\n        ''transaction_subtype'', mp.transaction_subtype,\n        ''direction'', mp.direction,\n        ''business_process'', mp.business_process,\n        ''phase'', mp.phase,\n        ''profile_key'', mp.profile_key,\n        ''profile'', mp.profile,\n        ''is_enabled'', mp.is_enabled\n      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)\n      from public.ediel_message_profiles mp\n      where mp.is_enabled = true\n    ), ''[]''::jsonb),\n    ''active_tenant_rule_profile_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rpv.id,\n        ''rule_profile_id'', rpv.rule_profile_id,\n        ''profile_key'', rpv.profile_key,\n        ''version'', rpv.version,\n        ''status'', rpv.status,\n        ''checksum'', rpv.checksum,\n        ''source_revision'', rpv.source_revision,\n        ''rules'', rpv.rules\n      ) order by rpv.profile_key, rpv.version, rpv.id)\n      from public.ediel_rule_profile_versions rpv\n      where rpv.company_id = p_company_id and rpv.status = ''active''\n    ), ''[]''::jsonb),\n    ''engine_version'', ''canonical-evidence-v3''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text, ''utf8''), ''sha256''), ''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id and configuration_hash = v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version), 0) + 1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,\n    test_brp_ediel_id, production_brp_ediel_id,\n    test_application_reference, production_application_reference,\n    primary_test_route_id, primary_production_route_id, payload, configuration_hash,\n    reason, created_by\n  ) values (\n    p_company_id,\n    v_next_version,\n    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n    v_company.test_ediel_id,\n    v_company.production_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.test_application_reference,\n    v_company.production_application_reference,\n    v_company.ediel_primary_test_route_profile_id,\n    v_company.ediel_primary_production_route_profile_id,\n    v_payload,\n    v_hash,\n    coalesce(nullif(btrim(p_reason), ''''), ''configuration_changed''),\n    p_actor_user_id\n  ) returning * into v_snapshot;\n\n  -- Exactly one durable readiness revalidation job per immutable snapshot.\n  insert into public.company_provisioning_jobs(\n    company_id,\n    job_key,\n    status,\n    idempotency_key,\n    available_at,\n    last_error_details\n  ) values (\n    p_company_id,\n    ''ediel_readiness_revalidate'',\n    ''pending'',\n    v_snapshot.id::text,\n    now(),\n    ''{}''::jsonb\n  )\n  on conflict (company_id, job_key, idempotency_key) do nothing;\n\n  update public.ediel_test_runs\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      stale_at = now()\n  where company_id = p_company_id\n    and completed_at is not null\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.actor_test_results\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      updated_at = now()\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_readiness_checks\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_go_live_events\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and event_type = ''production_dry_run''\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_state\n  set configuration_snapshot_id = v_snapshot.id,\n      state = case when state in (''prepared'', ''live'') then ''blocked'' else state end,\n      blocked_reason = case when state in (''prepared'', ''live'') then ''configuration_changed'' else blocked_reason end,\n      state_version = state_version + 1,\n      updated_at = now()\n  where company_id = p_company_id;\n\n  if exists(\n    select 1 from public.ediel_production_state\n    where company_id = p_company_id and state = ''blocked''\n  ) then\n    update public.companies\n    set production_status = ''blocked'',\n        ediel_production_status = ''blocked'',\n        live_ediel_enabled = false,\n        ediel_production_enabled = false,\n        live_blocked_reason = ''configuration_changed'',\n        updated_at = now()\n    where id = p_company_id;\n\n    insert into public.ediel_send_locks(\n      company_id, environment, locked, locked_reason, locked_at, updated_at\n    ) values (\n      p_company_id, ''production'', true, ''configuration_changed'', now(), now()\n    )\n    on conflict (company_id, environment) do update\n    set locked = true,\n        locked_reason = ''configuration_changed'',\n        locked_at = now(),\n        updated_at = now();\n  end if;\n\n  return v_snapshot;\nend;\n","patched":"\ndeclare\n  v_company public.companies%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\nbegin\n  if p_company_id is null then raise exception ''company_id_required''; end if;\n  select * into v_company from public.companies where id = p_company_id for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  v_payload := jsonb_build_object(\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n      ''test_ediel_id'', v_company.test_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', v_company.brp_ediel_id,\n      ''test_application_reference'', v_company.test_application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''test_sender_sub_address'', v_company.test_sender_sub_address,\n      ''production_sender_sub_address'', v_company.production_sender_sub_address,\n      ''test_mailbox'', v_company.test_mailbox,\n      ''production_mailbox'', v_company.production_mailbox,\n      ''primary_test_route_id'', v_company.ediel_primary_test_route_profile_id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', a.id,\n        ''environment'', a.environment,\n        ''actor_role'', coalesce(a.actor_role, a.role),\n        ''ediel_id'', coalesce(a.actor_ediel_id, a.ediel_id),\n        ''sender_subaddress'', coalesce(a.sender_sub_address, a.sender_subaddress),\n        ''receiver_subaddress'', coalesce(a.receiver_sub_address, a.receiver_subaddress),\n        ''application_reference'', coalesce(a.application_reference, a.default_application_reference),\n        ''mailbox'', a.mailbox,\n        ''brp_ediel_id'', a.brp_ediel_id,\n        ''is_active'', a.is_active\n      ) order by a.environment, a.id)\n      from public.ediel_actor_settings a\n      where a.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', r.id,\n        ''environment'', r.environment,\n        ''route_type'', r.route_type,\n        ''sender_ediel_id'', r.sender_ediel_id,\n        ''sender_subaddress'', coalesce(r.sender_sub_address, r.sender_subaddress),\n        ''receiver_ediel_id'', r.receiver_ediel_id,\n        ''receiver_subaddress'', coalesce(r.receiver_sub_address, r.receiver_subaddress),\n        ''mailbox_id'', r.mailbox_id,\n        ''transport_profile_id'', r.transport_profile_id,\n        ''certificate_id'', r.certificate_id,\n        ''receiver_certificate_id'', r.receiver_certificate_id,\n        ''is_active'', r.is_active,\n        ''is_enabled'', r.is_enabled\n      ) order by r.environment, r.id)\n      from public.ediel_route_profiles r\n      where r.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', m.id,\n        ''environment'', m.environment,\n        ''mailbox_name'', m.mailbox_name,\n        ''email_address'', m.email_address,\n        ''imap_host'', m.imap_host,\n        ''imap_port'', m.imap_port,\n        ''provider'', m.provider,\n        ''mailbox_type'', m.mailbox_type,\n        ''is_active'', m.is_active,\n        ''is_shared_platform_mailbox'', m.is_shared_platform_mailbox,\n        ''secret_reference_present'', m.secret_reference is not null\n      ) order by m.environment, m.id)\n      from public.ediel_mailboxes m\n      where m.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', c.id,\n        ''fingerprint'', c.certificate_fingerprint,\n        ''valid_from'', c.certificate_valid_from,\n        ''valid_to'', c.certificate_valid_to,\n        ''encryption_status'', c.encryption_status,\n        ''status'', c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''active_test_configurations'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''environment'', tc.environment,\n        ''test_suite'', tc.test_suite,\n        ''actor_role'', tc.actor_role,\n        ''message_family'', tc.message_family,\n        ''setup_package'', tc.setup_package,\n        ''status'', tc.status\n      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)\n      from public.ediel_active_test_configurations tc\n      where tc.company_id = p_company_id and tc.status = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rv.id,\n        ''rule_key'', rv.rule_key,\n        ''version_code'', rv.version_code,\n        ''schema_version'', rv.schema_version,\n        ''environment'', rv.environment,\n        ''message_family'', rv.message_family,\n        ''message_code'', rv.message_code,\n        ''business_process'', rv.business_process,\n        ''source_version'', rv.source_version,\n        ''status'', rv.status,\n        ''is_active'', rv.is_active\n      ) order by rv.rule_key, rv.version_code, rv.id)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active, false) = true\n        and coalesce(rv.status, ''active'') = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_packs'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rp.id,\n        ''market'', rp.market,\n        ''family'', rp.family,\n        ''guide_version'', rp.guide_version,\n        ''guide_revision'', rp.guide_revision,\n        ''unh_association_code'', rp.unh_association_code,\n        ''valid_from'', rp.valid_from,\n        ''valid_to'', rp.valid_to,\n        ''status'', rp.status,\n        ''source_hash'', rp.source_hash,\n        ''field_matrix_version'', rp.field_matrix_version,\n        ''code_list_versions'', rp.code_list_versions\n      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)\n      from public.ediel_rule_packs rp\n      where rp.status = ''active''\n    ), ''[]''::jsonb),\n    ''enabled_message_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', mp.id,\n        ''rule_pack_id'', mp.rule_pack_id,\n        ''message_code'', mp.message_code,\n        ''transaction_subtype'', mp.transaction_subtype,\n        ''direction'', mp.direction,\n        ''business_process'', mp.business_process,\n        ''phase'', mp.phase,\n        ''profile_key'', mp.profile_key,\n        ''profile'', mp.profile,\n        ''is_enabled'', mp.is_enabled\n      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)\n      from public.ediel_message_profiles mp\n      where mp.is_enabled = true\n    ), ''[]''::jsonb),\n    ''active_tenant_rule_profile_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rpv.id,\n        ''rule_profile_id'', rpv.rule_profile_id,\n        ''profile_key'', rpv.profile_key,\n        ''version'', rpv.version,\n        ''status'', rpv.status,\n        ''checksum'', rpv.checksum,\n        ''source_revision'', rpv.source_revision,\n        ''rules'', rpv.rules\n      ) order by rpv.profile_key, rpv.version, rpv.id)\n      from public.ediel_rule_profile_versions rpv\n      where rpv.company_id = p_company_id and rpv.status = ''active''\n    ), ''[]''::jsonb),\n    ''engine_version'', ''canonical-evidence-v3''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text, ''utf8''), ''sha256''), ''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id and configuration_hash = v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version), 0) + 1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,\n    test_brp_ediel_id, production_brp_ediel_id,\n    test_application_reference, production_application_reference,\n    primary_test_route_id, primary_production_route_id, payload, configuration_hash,\n    reason, created_by\n  ) values (\n    p_company_id,\n    v_next_version,\n    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n    v_company.test_ediel_id,\n    v_company.production_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.test_application_reference,\n    v_company.production_application_reference,\n    v_company.ediel_primary_test_route_profile_id,\n    v_company.ediel_primary_production_route_profile_id,\n    v_payload,\n    v_hash,\n    coalesce(nullif(btrim(p_reason), ''''), ''configuration_changed''),\n    p_actor_user_id\n  ) returning * into v_snapshot;\n\n  -- Exactly one durable readiness revalidation job per immutable snapshot.\n  insert into public.company_provisioning_jobs(\n    company_id,\n    job_key,\n    status,\n    idempotency_key,\n    available_at,\n    last_error_details\n  ) values (\n    p_company_id,\n    ''ediel_readiness_revalidate'',\n    ''pending'',\n    v_snapshot.id::text,\n    now(),\n    ''{}''::jsonb\n  )\n  on conflict (company_id, job_key, idempotency_key) do nothing;\n\n  update public.ediel_test_runs\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      stale_at = now()\n  where company_id = p_company_id\n    and completed_at is not null\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.actor_test_results\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      updated_at = now()\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_readiness_checks\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_go_live_events\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and event_type = ''production_dry_run''\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  -- This aggregate snapshot is retained for operations/dashboard continuity.\n  -- A dependency change invalidates only matching immutable capability proofs\n  -- on their next read; it must not pause an unrelated legal role/capability.\n  -- Explicit operator production state and send locks are preserved.\n  update public.ediel_production_state\n  set configuration_snapshot_id = v_snapshot.id,\n      updated_at = now()\n  where company_id = p_company_id;\n\n  return v_snapshot;\nend;\n","source_line":37187,"source_statement_sha256":"c7b77d20dc3f4aa613f03a4a1a32a73e7ef242925e23eba1fe0faa49c45fd7b7","expected":{"owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=public, extensions, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_company_id","p_actor_user_id","p_reason"],"proargmodes":null,"return_type":"ediel_configuration_snapshots","proretset":false,"identity_arguments":"p_company_id uuid, p_actor_user_id uuid, p_reason text","arguments":"p_company_id uuid, p_actor_user_id uuid, p_reason text","language":"plpgsql"}},{"signature":"public.canonical_capture_ediel_test_configuration_snapshot(uuid,uuid,uuid,uuid,text)","before":"cd351237978161ee32086f9b7832a0eb","after":"f8a8c3fa9b29b761dc47ebb0e465d3be","canonical_complete":"f8a8c3fa9b29b761dc47ebb0e465d3be","original":"\ndeclare\n  v_company public.companies%rowtype;\n  v_actor public.ediel_actor_settings%rowtype;\n  v_route public.ediel_route_profiles%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\n  v_actor_role text;\n  v_actor_ediel_id text;\n  v_route_sender text;\n  v_route_receiver text;\nbegin\n  if p_company_id is null or p_actor_profile_id is null or p_route_profile_id is null then\n    raise exception ''company_actor_profile_and_route_required'';\n  end if;\n  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, ''ediel.profile.write'', false) then\n    raise exception ''actor_not_authorized_for_test_configuration_snapshot'';\n  end if;\n\n  select * into v_company\n  from public.companies\n  where id=p_company_id\n  for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  select * into v_actor\n  from public.ediel_actor_settings\n  where id=p_actor_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_actor_profile_not_found''; end if;\n  if lower(coalesce(v_actor.environment,'''')) <> ''test'' or coalesce(v_actor.is_active,false) <> true then\n    raise exception ''test_actor_profile_must_be_active_test_profile'';\n  end if;\n\n  v_actor_role := case lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n    when ''supplier'' then ''supplier''\n    when ''electricity_supplier'' then ''supplier''\n    when ''esco'' then ''energy_service_company''\n    when ''energy_service_company'' then ''energy_service_company''\n    else lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n  end;\n  v_actor_ediel_id := nullif(btrim(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id)), '''');\n  if v_actor_role is null or v_actor_ediel_id is null then\n    raise exception ''test_actor_profile_identity_incomplete'';\n  end if;\n\n  select * into v_route\n  from public.ediel_route_profiles\n  where id=p_route_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_route_profile_not_found''; end if;\n  if lower(coalesce(v_route.environment,'''')) <> ''test''\n     or coalesce(v_route.is_active,true) <> true\n     or coalesce(v_route.is_enabled,true) <> true then\n    raise exception ''test_route_profile_must_be_active_test_route'';\n  end if;\n\n  v_route_sender := nullif(btrim(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id)), '''');\n  v_route_receiver := nullif(btrim(coalesce(v_route.receiver_ediel_id,v_route.counterparty_ediel_id)), '''');\n  if v_route_sender is null or upper(v_route_sender) <> upper(v_actor_ediel_id) then\n    raise exception ''test_route_sender_must_match_actor_profile'';\n  end if;\n  if v_route_receiver is null then\n    raise exception ''test_route_receiver_required'';\n  end if;\n  if v_route.actor_setting_id is not null and v_route.actor_setting_id <> v_actor.id then\n    raise exception ''test_route_actor_binding_mismatch'';\n  end if;\n\n  v_payload := jsonb_build_object(\n    ''test_context'', jsonb_build_object(\n      ''actor_profile_id'', v_actor.id,\n      ''route_profile_id'', v_route.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''counterparty_ediel_id'', v_route_receiver,\n      ''message_family'', upper(coalesce(v_route.message_family,'''')),\n      ''application_reference'', v_route.application_reference,\n      ''environment_type'', v_route.environment_type\n    ),\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),\n      ''test_application_reference'', v_route.application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''primary_test_route_id'', v_route.id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',a.id,''environment'',a.environment,''actor_role'',coalesce(a.actor_role,a.role),\n        ''ediel_id'',coalesce(a.actor_ediel_id,a.ediel_id),\n        ''sender_subaddress'',coalesce(a.sender_sub_address,a.sender_subaddress),\n        ''receiver_subaddress'',coalesce(a.receiver_sub_address,a.receiver_subaddress),\n        ''application_reference'',coalesce(a.application_reference,a.default_application_reference),\n        ''mailbox'',a.mailbox,''brp_ediel_id'',a.brp_ediel_id,''is_active'',a.is_active\n      ) order by a.environment,a.id)\n      from public.ediel_actor_settings a\n      where a.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',r.id,''environment'',r.environment,''route_type'',r.route_type,\n        ''actor_setting_id'',r.actor_setting_id,\n        ''sender_ediel_id'',r.sender_ediel_id,\n        ''sender_subaddress'',coalesce(r.sender_sub_address,r.sender_subaddress),\n        ''receiver_ediel_id'',r.receiver_ediel_id,\n        ''receiver_subaddress'',coalesce(r.receiver_sub_address,r.receiver_subaddress),\n        ''application_reference'',r.application_reference,\n        ''message_family'',r.message_family,\n        ''environment_type'',r.environment_type,\n        ''mailbox_id'',r.mailbox_id,''transport_profile_id'',r.transport_profile_id,\n        ''certificate_id'',r.certificate_id,''receiver_certificate_id'',r.receiver_certificate_id,\n        ''transport_security_mode'',r.transport_security_mode,\n        ''is_active'',r.is_active,''is_enabled'',r.is_enabled\n      ) order by r.environment,r.id)\n      from public.ediel_route_profiles r\n      where r.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',m.id,''environment'',m.environment,''mailbox_name'',m.mailbox_name,\n        ''email_address'',m.email_address,''provider'',m.provider,''mailbox_type'',m.mailbox_type,\n        ''transport_mode'',m.transport_mode,''tls_required'',m.tls_required,\n        ''signing_mode'',m.signing_mode,''encryption_mode'',m.encryption_mode,\n        ''is_active'',m.is_active,''is_shared_platform_mailbox'',m.is_shared_platform_mailbox\n      ) order by m.environment,m.id)\n      from public.ediel_mailboxes m\n      where m.company_id=p_company_id or m.id=v_route.mailbox_id\n    ),''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',c.id,''fingerprint'',coalesce(c.fingerprint_sha256,c.certificate_fingerprint),\n        ''owner_ediel_id'',c.owner_ediel_id,''owner_subaddress'',c.owner_subaddress,\n        ''message_family'',c.message_family,''purpose'',c.purpose,''usage'',c.usage,\n        ''valid_from'',coalesce(c.valid_from,c.certificate_valid_from),\n        ''valid_to'',coalesce(c.valid_to,c.certificate_valid_to),\n        ''encryption_status'',c.encryption_status,''status'',c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.id in (v_route.certificate_id,v_route.receiver_certificate_id)\n    ),''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''rule_key'',rv.rule_key,''version_code'',rv.version_code,''schema_version'',rv.schema_version,\n        ''environment'',rv.environment,''status'',rv.status,''is_active'',rv.is_active\n      ) order by rv.rule_key,rv.version_code)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active,false)=true and coalesce(rv.status,''active'')=''active''\n    ),''[]''::jsonb),\n    ''engine_version'',''canonical-evidence-v3-role-scoped''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text,''utf8''),''sha256''),''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id and configuration_hash=v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version),0)+1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id,snapshot_version,actor_role,test_ediel_id,production_ediel_id,\n    test_brp_ediel_id,production_brp_ediel_id,\n    test_application_reference,production_application_reference,\n    primary_test_route_id,primary_production_route_id,payload,configuration_hash,\n    reason,created_by\n  ) values (\n    p_company_id,v_next_version,v_actor_role,v_actor_ediel_id,v_company.production_ediel_id,\n    coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),v_company.brp_ediel_id,\n    v_route.application_reference,v_company.production_application_reference,\n    v_route.id,v_company.ediel_primary_production_route_profile_id,\n    v_payload,v_hash,coalesce(nullif(btrim(p_reason),''''),''test_configuration_changed''),p_actor_user_id\n  ) returning * into v_snapshot;\n\n  update public.ediel_test_runs r\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',stale_at=now()\n  where r.company_id=p_company_id\n    and r.completed_at is not null\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  update public.actor_test_results ar\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',updated_at=now()\n  from public.ediel_test_runs r\n  where ar.company_id=p_company_id\n    and ar.ediel_test_run_id=r.id\n    and r.company_id=p_company_id\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  return v_snapshot;\nend;\n","patched":"\ndeclare\n  v_company public.companies%rowtype;\n  v_actor public.ediel_actor_settings%rowtype;\n  v_route public.ediel_route_profiles%rowtype;\n  v_communication_route public.communication_routes%rowtype;\n  v_payload jsonb;\n  v_h